/// Brand mark for a provider id. Unknown ids keep the document fallback.
pub fn icon(provider_id: &str) -> &'static str {
    let name = provider_id
        .split('/')
        .next()
        .unwrap_or("")
        .to_ascii_lowercase();
    match name.as_str() {
        "codex" | "openai" => OPENAI,
        "claude" | "anthropic" => ANTHROPIC,
        "cursor" => CURSOR,
        "grok" | "xai" => GROK,
        "nous" => NOUS,
        "opencode" | "opencode-go" => OPENCODE,
        "amp" => AMP,
        "zai" => ZAI,
        "minimax" => MINIMAX,
        "kimi" | "moonshot" => KIMI,
        "copilot" | "github" => COPILOT,
        "devin" => DEVIN,
        "kiro" => KIRO,
        "antigravity" => ANTIGRAVITY,
        "perplexity" => PERPLEXITY,
        "factory" => FACTORY,
        "synthetic" => SYNTHETIC,
        "jetbrains" | "jetbrains-ai-assistant" => JETBRAINS,
        "azureopenai" => AZUREOPENAI,
        "atlascloud" => ATLASCLOUD,
        "chutes" => CHUTES,
        "clinepass" => CLINEPASS,
        "commandcode" => COMMANDCODE,
        "deepinfra" => DEEPINFRA,
        "deepseek" => DEEPSEEK,
        "elevenlabs" => ELEVENLABS,
        "fireworks" => FIREWORKS,
        "gemini" => GEMINI,
        "groq" => GROQ,
        "huggingface" => HUGGINGFACE,
        "ibmbob" => IBMBOB,
        "kilo" => KILO,
        "manus" => MANUS,
        "ollama" => OLLAMA,
        "openrouter" => OPENROUTER,
        "poe" => POE,
        "v0" => V0,
        "venice" => VENICE,
        "vercel" => VERCEL,
        "zenmux" => ZENMUX,
        "alibaba" | "alibabatokenplan" => ALIBABA,
        "qwencloud" => QWENCLOUD,
        "vertexai" => VERTEXAI,
        "windsurf" => WINDSURF,
        "mimo" => MIMO,
        "doubao" => DOUBAO,
        "sakana" => SAKANA,
        "mistral" => MISTRAL,
        "qoder" => QODER,
        "stepfun" => STEPFUN,
        "bedrock" => BEDROCK,
        "longcat" => LONGCAT,
        "notion" => NOTION,
        "replicate" => REPLICATE,
        "pi" => PI,
        "aiand" => AIAND,
        "bifrost" => BIFROST,
        "clawrouter" => CLAWROUTER,
        "codebuff" => CODEBUFF,
        "coderabbit" => CODERABBIT,
        "deepgram" => DEEPGRAM,
        "devpass" => DEVPASS,
        "gitkraken" => GITKRAKEN,
        "hyper" => HYPER,
        "litellm" => LITELLM,
        "llmman" => LLMMAN,
        "llmproxy" => LLMPROXY,
        "muse" => MUSE,
        "neuralwatt" => NEURALWATT,
        "sub2api" => SUB2API,
        "warp" => WARP,
        "wayfinder" => WAYFINDER,
        "augment" => AUGMENT,
        "t3chat" => T3CHAT,
        "zed" => ZED,
        "abacus" => ABACUS,
        "helmcode" => HELMCODE,
        "zoommate" => ZOOMMATE,
        "typesafe" => TYPESAFE,
        _ => FALLBACK,
    }
}

#[cfg(test)]
mod tests {
    use super::icon;

    #[test]
    fn dev_registry_ids_keep_a_mark() {
        for id in [
            "azureopenai",
            "openai",
            "clinepass",
            "alibaba",
            "alibabatokenplan",
            "qwencloud",
            "fireworks",
            "gemini",
            "manus",
            "kilo",
            "vertexai",
            "augment",
            "t3chat",
            "ollama",
            "openrouter",
            "elevenlabs",
            "warp",
            "windsurf",
            "zed",
            "mimo",
            "doubao",
            "sakana",
            "abacus",
            "mistral",
            "deepseek",
            "deepinfra",
            "codebuff",
            "venice",
            "commandcode",
            "qoder",
            "stepfun",
            "bedrock",
            "groq",
            "llmproxy",
            "litellm",
            "bifrost",
            "deepgram",
            "poe",
            "chutes",
            "neuralwatt",
            "helmcode",
            "clawrouter",
            "longcat",
            "sub2api",
            "wayfinder",
            "zenmux",
            "aiand",
            "zoommate",
            "notion",
            "ibmbob",
            "muse",
            "coderabbit",
            "replicate",
            "huggingface",
            "pi",
            "v0",
            "typesafe",
            "hyper",
            "gitkraken",
            "devpass",
            "atlascloud",
            "vercel",
            "llmman",
        ] {
            let svg = icon(id);
            assert!(!svg.contains("data-icon=\"fallback\""), "{id}");
            assert!(svg.contains("<title>"), "{id}");
        }
    }

    #[test]
    fn unknown_provider_uses_the_fallback_document() {
        assert!(icon("mystery").contains("data-icon=\"fallback\""));
    }
}
